#!/usr/bin/env bash
# Offline checks for everything Flux and OpenTofu would apply. Runs in CI on
# changes to platform/ (the repo's .github/workflows/platform.yaml) and locally the same way:
#   scripts/validate.sh
# Touches nothing: no cluster, no OpenTofu state, no credentials, no decryption.
set -euo pipefail
cd "$(dirname "$0")/.."

# Kubernetes manifests: what each Flux Kustomization builds, validated against
# the Kubernetes schemas plus CRD schemas from the community catalog. Kinds
# missing from the catalog are skipped rather than failed. scripts/schemas/
# (generated by scripts/crd-schemas.sh) is checked first, for CRDs whose
# catalog copy is outdated. -strict rejects unknown fields (typos); Secrets are
# skipped because SOPS adds a `sops` block, and they're generated by kubectl
# anyway.
# apps/run-demo is applied by its own Kustomization (registered in
# apps/maxcloud), not as part of `apps`.
for dir in clusters/personal infrastructure/controllers infrastructure/configs apps apps/run-demo; do
  echo "--- kustomize build $dir"
  kustomize build "$dir" | kubeconform -summary -strict -ignore-missing-schemas -skip Secret \
    -schema-location default \
    -schema-location 'scripts/schemas/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json' \
    -schema-location 'https://raw.githubusercontent.com/datreeio/CRDs-catalog/main/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json'
done

# The app template's manifests aren't built by any Flux Kustomization, so
# check its files directly. `image: app` is a placeholder the deploy workflow
# fills in.
echo "--- templates/run-app"
kubeconform -summary -strict -ignore-missing-schemas \
  -schema-location default \
  -schema-location 'https://raw.githubusercontent.com/datreeio/CRDs-catalog/main/{{.Group}}/{{.ResourceKind}}_{{.ResourceAPIVersion}}.json' \
  templates/run-app/deploy/k8s/*.yaml templates/run-app/deploy/examples/*.yaml

# OpenTofu stacks, without backends or credentials. -lockfile=readonly fails if
# .terraform.lock.hcl doesn't match the required providers (e.g. a provider
# bump without matching lock file hashes).
for stack in infra/*/; do
  echo "--- tofu validate $stack"
  tofu -chdir="$stack" fmt -check -diff
  tofu -chdir="$stack" init -backend=false -lockfile=readonly -input=false >/dev/null
  tofu -chdir="$stack" validate
done

# The knowledge base: frontmatter, index and links (docs/kb/).
echo "--- docs/kb"
scripts/kb-check.sh
